import uuid
from django.db import migrations, models


def repair_providers(apps, schema_editor):
    for model in apps.get_app_config('leakscope_app').get_models():
        fields = {field.name for field in model._meta.fields}
        if 'provider' not in fields or model.__name__ in ('Search', 'CustomQuery', 'Run'):
            continue
        if 'search' in fields:
            for obj in model.objects.select_related('search').iterator():
                provider = obj.search.provider if obj.search_id else 'unknown'
                if provider not in ('shodan', 'zoomeye'):
                    provider = 'unknown'
                if obj.provider != provider:
                    model.objects.filter(pk=obj.pk).update(provider=provider)
        else:
            # Legacy direct collectors defaulted to Shodan without a provider request.
            model.objects.filter(provider__in=['', 'shodan']).update(provider='unknown')


